		testhelp.Equal(t, "WWW-Authenticate", rec.Header().Get("WWW-Authenticate"), `Basic realm="morph-studio"`)
		testhelp.Equal(t, "body", rec.Body.String(), `{"error":{"code":"unauthorized"}}`+"\n")
	}
